// Map chat-bot-service's contract (uppercase USER/ASSISTANT roles, per
// apps/chat-bot-service/src/message/message.service.ts's ChatRole) onto
// llm-service's contract (lowercase user/assistant, app/schemas.py).
// sessionId/userId aren't needed for generation, so they're dropped here.
const body = $input.first().json.body ?? $input.first().json;

const history = (body.history || []).map((turn) => ({
  role: turn.role === 'ASSISTANT' ? 'assistant' : 'user',
  content: turn.content,
}));

return [
  {
    json: {
      message: body.message,
      history,
    },
  },
];
